## 5. Full Minimal Example (copy‑paste)

```go
package myworkflow_test

import (
    "context"
    "encoding/json"
    "errors"
    "testing"

    "go.temporal.io/sdk/nexus"
    "go.temporal.io/sdk/nexus/registry"
    "go.temporal.io/sdk/testsuite"
    "go.temporal.io/sdk/workflow"
)

// ---------- Workflow under test ----------
func MyWorkflow(ctx workflow.Context, input string) (string, error) {
    var result string
    err := workflow.ExecuteNexusOperation(
        ctx,
        nexus.OperationOptions{
            Service:   "my-service",
            Operation: "async-op",
        },
        input,
        &result,
    ).Get(ctx, &result)
    return result, err
}

// ---------- Mock async operation ----------
type mockAsyncOp struct {
    request    string
    completeCh chan struct{}
    result     []byte
    err        error
}

func (m *mockAsyncOp) Complete(result []byte) error {
    m.result = result
    close(m.completeCh)
    return nil
}
func (m *mockAsyncOp) Fail(f *nexus.Failure) error {
    m.err = errors.New(f.Message)
    close(m.completeCh)
    return nil
}
func (m *mockAsyncOp) Wait() { <-m.completeCh }

// ---------- Test ----------
func Test_MyWorkflow_WithMockedNexus(t *testing.T) {
    var ts testsuite.WorkflowTestSuite
    env := ts.NewTestWorkflowEnvironment()

    // 1️⃣ Create a mock registry
    mockReg := registry.New()

    // Async operation registration
    mockReg.RegisterOperation(
        "async-op",
        registry.OperationOptions{Async: true},
        func(ctx context.Context, input []byte) (registry.AsyncOperation, error) {
            var payload string
            _ = json.Unmarshal(input, &payload)
            return &mockAsyncOp{
                request:    payload,
                completeCh: make(chan struct{}),
            }, nil
        },
    )

    // Sync operation registration (example)
    mockReg.RegisterOperation(
        "sync-op",
        registry.OperationOptions{},
        func(ctx context.Context, input []byte) (any, error) {
            var p struct{ Value int }
            _ = json.Unmarshal(input, &p)
            return struct{ Doubled int `json:"doubled"` }{Doubled: p.Value * 2}, nil
        },
    )

    // Wire the registry into the test env
    env.SetNexusServiceRegistry(mockReg)

    // Execute the workflow
    env.ExecuteWorkflow(MyWorkflow, `"hello"`)

    // Grab the async op instance
    asyncOp := mockReg.GetOperationInstance("async-op").(*mockAsyncOp)

    // Optional: assert request payload
    if asyncOp.request != `"hello"` {
        t.Fatalf("unexpected request: %s", asyncOp.request)
    }

    // Simulate successful completion
    if err := asyncOp.Complete([]byte(`"world"`)); err != nil {
        t.Fatalf("complete error: %v", err)
    }

    // Verify workflow outcome
    if !env.IsWorkflowCompleted() {
        t.Fatalf("workflow never completed")
    }
    var got string
    if err := env.GetWorkflowResult(&got); err != nil {
        t.Fatalf("workflow error: %v", err)
    }
    if got != "world" {
        t.Fatalf("expected 'world', got %q", got)
    }
}
```

